import * as Phaser from 'phaser';
import { TUNING } from '../config/tuning';

/**
 * Asset manifest — `public/assets/manifest.json` (generated by
 * `node art/tools/build-manifest.mjs` from the Blender render outputs).
 *
 * To swap art: drop a new PNG (+ its .json anchor file) over the old one and
 * re-run the manifest script. Code only ever refers to asset KEYS. Anything the
 * manifest does not provide is replaced by a coloured placeholder at runtime,
 * so the game always runs.
 */
export interface SpriteMeta {
    file: string;
    w: number;
    h: number;
    anchorX: number;
    anchorY: number;
    ppm: number;
}
export interface AtlasMeta {
    image: string;
    json: string;
    anchorX: number;
    anchorY: number;
    cellW: number;
    cellH: number;
    ppm: number;
    anims: Record<string, { frames: number; fps: number; dirs: number }>;
    /** sasquatch: palm of the raised hand in the "get" pose, per direction (m from the feet) */
    get?: { hand?: Record<string, number[]> };
    drive?: unknown;
    seat?: unknown;
    footprint?: number[];
}
export interface Manifest {
    sprites: Record<string, SpriteMeta>;
    atlases: Record<string, AtlasMeta>;
    svgs: Record<string, { file: string; w: number; h: number }>;
    images: Record<string, string>;
    audio: Record<string, string>;
    json: Record<string, string>;
}

let manifest: Manifest = { sprites: {}, atlases: {}, svgs: {}, images: {}, audio: {}, json: {} };

export function setManifest(m: Partial<Manifest>) {
    manifest = { sprites: {}, atlases: {}, svgs: {}, images: {}, audio: {}, json: {}, ...m };
}
export function getManifest() {
    return manifest;
}

export function queueManifestAssets(scene: Phaser.Scene) {
    const L = scene.load;
    L.setPath('assets/');
    for (const [k, m] of Object.entries(manifest.sprites)) {
        if (m.file.endsWith('.svg')) L.svg(k, m.file, { width: m.w, height: m.h });
        else L.image(k, m.file);
    }
    // character atlases use Phaser's multi-atlas format (they may span several pages)
    for (const [k, m] of Object.entries(manifest.atlases)) L.multiatlas(k, m.json, 'assets/' + m.json.slice(0, m.json.lastIndexOf('/') + 1));
    for (const [k, m] of Object.entries(manifest.svgs)) L.svg(k, m.file, { width: m.w, height: m.h });
    for (const [k, f] of Object.entries(manifest.images)) {
        if (f.endsWith('.svg')) L.svg(k, f);
        else L.image(k, f);
    }
    for (const [k, f] of Object.entries(manifest.audio)) L.audio(k, f);
    for (const [k, f] of Object.entries(manifest.json)) L.json(k, f);
    L.setPath('');
}

/** Placeholder description used when a prop sprite has not been rendered yet. */
export interface PlaceholderSpec {
    w: number;         // metres
    h: number;         // metres (visual height)
    color: number;
    shape?: 'box' | 'blob' | 'tree' | 'cone';
}

/**
 * Returns sprite meta for `key`. If the manifest lacks it, builds a simple
 * placeholder texture from `spec` (and caches it under the same key).
 */
export function spriteMeta(scene: Phaser.Scene, key: string, spec?: PlaceholderSpec): SpriteMeta {
    const m = manifest.sprites[key];
    if (m && scene.textures.exists(key)) return m;
    const ppm = TUNING.render.spritePPM / 4;
    const s = spec ?? { w: 1, h: 1, color: 0xff00ff, shape: 'box' };
    const W = Math.max(8, Math.round(s.w * ppm));
    const H = Math.max(8, Math.round(s.h * ppm));
    const meta: SpriteMeta = { file: '', w: W, h: H, anchorX: W / 2, anchorY: H - 2, ppm };
    if (!scene.textures.exists(key)) {
        const g = scene.make.graphics({ x: 0, y: 0 }, false);
        g.fillStyle(s.color, 1);
        switch (s.shape) {
            case 'tree':
                g.fillStyle(0x6b4a2b, 1);
                g.fillRect(W / 2 - W * 0.06, H * 0.7, W * 0.12, H * 0.3);
                g.fillStyle(s.color, 1);
                g.fillTriangle(W / 2, 0, 0, H * 0.82, W, H * 0.82);
                break;
            case 'blob':
                g.fillEllipse(W / 2, H / 2, W, H);
                break;
            case 'cone':
                g.fillTriangle(W / 2, 0, 0, H, W, H);
                break;
            default:
                g.fillRoundedRect(0, 0, W, H, Math.min(W, H) * 0.12);
        }
        g.generateTexture(key, W, H);
        g.destroy();
    }
    manifest.sprites[key] = meta;
    return meta;
}

export function hasAtlas(key: string) {
    return !!manifest.atlases[key];
}
export function atlasMeta(key: string): AtlasMeta | undefined {
    return manifest.atlases[key];
}
